<?php
require_once dirname(__DIR__) . '/_common.php';$pageTitle='Tambah kegiatan';$error='';$statuses=['rencana','berlangsung','selesai'];
if(osis_admin_is_post()){osis_verify_csrf();$judul=osis_post_string('judul',180);$deskripsi=osis_post_string('deskripsi',10000);$tanggal=osis_post_string('tanggal',10);$lokasi=osis_post_string('lokasi',150);$status=isset($_POST['status'])?(string)$_POST['status']:'rencana';if($judul===''||$deskripsi===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggal)||!in_array($status,$statuses,true)){$error='Judul, deskripsi, tanggal, dan status harus diisi dengan benar.';}else{try{$gambar=osis_store_uploaded_image(isset($_FILES['gambar'])?$_FILES['gambar']:null,'kegiatan');$stmt=$pdo->prepare('INSERT INTO kegiatan(judul,deskripsi,tanggal,lokasi,status,gambar) VALUES(?,?,?,?,?,?)');$stmt->execute([$judul,$deskripsi,$tanggal,$lokasi?:null,$status,$gambar]);osis_log_activity('Menambahkan kegiatan: '.$judul);osis_set_flash('success','Kegiatan berhasil ditambahkan.');osis_redirect('admin/kegiatan/index.php');}catch(Throwable $exception){$error=osis_admin_handle_error($exception);}}}
osis_admin_page_start($pageTitle);
?>
<div class="admin-form-wrap"><a class="back-link" href="<?=osis_e(osis_url('admin/kegiatan/index.php'))?>">← Daftar kegiatan</a><div class="admin-panel form-panel"><span class="eyebrow">AGENDA OSIS</span><h2>Tambah kegiatan</h2><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" data-validate-form><?=osis_csrf_input()?><label for="judul">Nama kegiatan</label><input id="judul" name="judul" required maxlength="180" value="<?=osis_e(isset($_POST['judul'])?$_POST['judul']:'')?>"><label for="deskripsi">Deskripsi</label><textarea id="deskripsi" name="deskripsi" rows="7" required><?=osis_e(isset($_POST['deskripsi'])?$_POST['deskripsi']:'')?></textarea><div class="form-grid"><div><label for="tanggal">Tanggal</label><input id="tanggal" name="tanggal" type="date" required value="<?=osis_e(isset($_POST['tanggal'])?$_POST['tanggal']:date('Y-m-d'))?>"></div><div><label for="lokasi">Lokasi</label><input id="lokasi" name="lokasi" maxlength="150" value="<?=osis_e(isset($_POST['lokasi'])?$_POST['lokasi']:'')?>"></div><div><label for="status">Status</label><select id="status" name="status"><?php foreach($statuses as $status):?><option value="<?=osis_e($status)?>" <?=isset($_POST['status'])?($_POST['status']===$status?'selected':''):($status==='rencana'?'selected':'')?>><?=osis_e(ucfirst($status))?></option><?php endforeach;?></select></div></div><label for="gambar">Gambar kegiatan <span class="optional">JPG, PNG, WEBP · maks. 5 MB</span></label><input id="gambar" name="gambar" type="file" accept="image/jpeg,image/png,image/webp"><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/kegiatan/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Simpan kegiatan <span>↗</span></button></div></form></div></div>
<?php osis_admin_page_end(); ?>
